// Types of the knowledge-graph nodes as the site uses them.
//
// types.generated.ts mirrors schema/*.json one to one (generated by scripts/gen-types.mjs; optional lists are
// optional there). The loader in data.ts keeps every YAML key and fills each optional list with [], so pages
// and endpoints work with the "loaded" types below. FILLED is the one list that drives both the runtime fill
// (data.ts) and these types, so the two cannot drift; a key that is not in the schema fails the type check.
export * from './types.generated.ts';
import type {
  Crosswalk as SchemaCrosswalk,
  CrosswalkConfidence,
  FailureMode as SchemaFailureMode,
  Incident as SchemaIncident,
  Paper as SchemaPaper,
  Recipe as SchemaRecipe,
  SaicaAxis,
  Taxonomy as SchemaTaxonomy,
  Tool as SchemaTool,
} from './types.generated.ts';

/** List fields the loader always returns as an array, per node kind (directory name under data/). */
export const FILLED = {
  tools: [
    'addresses_failure_modes',
    'records_failure_modes',
    'locus_of_control',
    'implements_techniques',
    'integration_surfaces',
    'composes_with',
    'feeds_into',
    'supersedes',
    'runtime_requires',
    'supervises_targets',
    'cited_in',
    'documented_in',
    'evaluated_on',
    'contributors',
  ],
  failure_modes: ['aliases', 'related_modes', 'prior_work', 'detection_signals'],
  taxonomies: ['categories'],
  papers: ['authors', 'relevance_tags'],
  crosswalks: ['authored_by', 'reviewed_by', 'mappings', 'unmapped'],
  incidents: ['exhibited_failure_modes', 'affected_systems', 'source_urls', 'documented_by', 'mitigated_by'],
  recipes: ['targets_failure_modes', 'stack'],
} as const;

export type NodeKind = keyof typeof FILLED;

type Filled<T, K extends keyof T> = Omit<T, K> & { [P in K]-?: NonNullable<T[P]> };

export type Tool = Filled<SchemaTool, (typeof FILLED.tools)[number]>;
/** The inline `crosswalks` list of a failure-mode file is not loaded: mappings live in data/crosswalks/ only
 *  and reach the site through `crosswalkEdges` (data.ts). */
export type FailureMode = Omit<Filled<SchemaFailureMode, (typeof FILLED.failure_modes)[number]>, 'crosswalks'>;
export type Taxonomy = Filled<SchemaTaxonomy, (typeof FILLED.taxonomies)[number]>;
export type Paper = Filled<SchemaPaper, (typeof FILLED.papers)[number]>;
export type Crosswalk = Filled<SchemaCrosswalk, (typeof FILLED.crosswalks)[number]>;
export type Incident = Filled<SchemaIncident, (typeof FILLED.incidents)[number]>;
export type Recipe = Filled<SchemaRecipe, (typeof FILLED.recipes)[number]>;

/** One mapping between a value on a SAICA axis (today always a failure mode) and a category of an external
 *  taxonomy. The single normalised form of data/crosswalks/*.yml; see `crosswalkEdges` in data.ts. */
export interface CrosswalkEdge {
  /** Id of the crosswalk node (file in data/crosswalks/) the mapping comes from. */
  crosswalk: string;
  axis: SaicaAxis;
  /** Value on the SAICA axis, e.g. a failure-mode id. */
  saica_value: string;
  taxonomy: string;
  taxonomy_name: string;
  external_id: string;
  external_label: string;
  confidence: CrosswalkConfidence;
  note?: string;
}

export interface Graph {
  tools: Record<string, Tool>;
  failureModes: Record<string, FailureMode>;
  taxonomies: Record<string, Taxonomy>;
  papers: Record<string, Paper>;
  crosswalks: Record<string, Crosswalk>;
  incidents: Record<string, Incident>;
  recipes: Record<string, Recipe>;
  // Derived index (crosswalk mappings are not on the graph: use crosswalkEdges from data.ts):
  toolsByFailureMode: Record<string, string[]>;
  /** From data/MANIFEST.json (`kg_version`), not typed in. */
  kgVersion: string;
  /** From data/MANIFEST.json (`generated_at`, ISO 8601), not the build clock. */
  kgLastUpdated: string;
}
